// Recebe o resultado de UMA cidade do Puppeteer
const dados = $input.first().json;

const cidade = dados.cidade || 'Desconhecida';
const cidadeIndex = dados.cidade_index || 0;
const totalCidades = dados.total_cidades || 0;
const success = dados.success || false;
const faixas = dados.faixas || [];
const error = dados.error || null;
const operadoras = dados.operadoras_disponiveis || [];

let mensagem = `*📍 COTAÇÃO ${cidadeIndex}/${totalCidades}*\n`;
mensagem += `*${cidade}*\n`;
mensagem += `${'─'.repeat(25)}\n\n`;

if (success && faixas.length > 0) {
  mensagem += `✅ Cotação Hapvida obtida\n\n`;
  faixas.forEach(f => {
    mensagem += `${f.faixa_etaria}: ${f.valor}\n`;
  });
} else {
  mensagem += `❌ ${error || 'Hapvida não disponível'}\n`;
  if (operadoras.length > 0) {
    mensagem += `\nOperadoras disponíveis:\n`;
    operadoras.forEach(op => {
      mensagem += `• ${op}\n`;
    });
  }
}

if (cidadeIndex === totalCidades) {
  mensagem += `\n${'='.repeat(25)}\n`;
  mensagem += `✅ Todas as ${totalCidades} cidades processadas!`;
}

return [{ 
  json: { 
    mensagem_whatsapp: mensagem,
    dados_originais: dados
  } 
}];
